const items = $input.all();
const saida = [];

function classificaTipo(titulo) {
  const t = String(titulo || '').toLowerCase();
  const palavras = ['exame', 'coleta', 'laboratorio', 'exames', 'sangue', 'ultrassom'];
  const palavrasConsulta = ['consulta', 'retorno', 'retorno de consulta', 'clinico', 'ambulatorio'];
  if (palavras.some(p => t.includes(p))) return 'exame';
  if (palavrasConsulta.some(p => t.includes(p))) return 'consulta';
  return 'outro';
}

for (const item of items) {
  const ev = item.json;
  const titulo = ev.summary || '';

  let inicio = null;
  let fim = null;
  if (ev.start) {
    inicio = ev.start.dateTime || (ev.start.date ? ev.start.date + 'T12:00:00' : null);
  }
  if (ev.end) {
    fim = ev.end.dateTime || (ev.end.date ? ev.end.date + 'T13:00:00' : null);
  }

  saida.push({
    json: {
      calendar_event_id: ev.id,
      titulo: titulo,
      tipo: classificaTipo(titulo),
      inicio: inicio,
      fim: fim,
      paciente_nome: null
    }
  });
}

return saida;
